use std::{env,fs};
const MAGIC:u32=0x50424638;const KNOWN_MASK:u32=0x3f;const STATEMENT:u64=0xfedcba9876543210;const AUTHORITY:u32=0xa17e0007;const EPOCH:u32=7;
fn mask(v:u16)->Option<u32>{match v{3=>Some(0x0f),4=>Some(0x1f),5=>Some(0x3f),6=>Some(0x7f),_=>None}}
fn digest(v:u16,m:u32)->Option<u64>{match (v,m){(3,0x0f)=>Some(0xafe980699da8615e),(4,0x1f)=>Some(0x72d93232cabe3db4),(5,0x3f)=>Some(0x934adf291e9db1f8),(6,0x7f)=>Some(0xd9a0e3046c894f9d),_=>None}}
fn hex(s:&str)->Option<Vec<u8>>{if s.len()%2!=0{return None}let mut o=Vec::new();for i in (0..s.len()).step_by(2){o.push(u8::from_str_radix(&s[i..i+2],16).ok()?);}Some(o)}
fn u16be(b:&[u8],i:usize)->u16{u16::from_be_bytes([b[i],b[i+1]])}fn u32be(b:&[u8],i:usize)->u32{u32::from_be_bytes([b[i],b[i+1],b[i+2],b[i+3]])}fn u64be(b:&[u8],i:usize)->u64{u64::from_be_bytes([b[i],b[i+1],b[i+2],b[i+3],b[i+4],b[i+5],b[i+6],b[i+7]])}
fn policy(h:&str)->Option<(u16,u32,u64)>{let b=hex(h)?;if b.len()!=16||u16be(&b,2)!=0{return None}Some((u16be(&b,0),u32be(&b,4),u64be(&b,8)))}
fn validate(b:&[u8],mode:&str,av:u16,ph:Option<&str>)->bool{if b.len()!=56{return false}let magic=u32be(b,0);let v=u16be(b,4);let flags=u16be(b,6);let m=u32be(b,8);let d=u64be(b,12);let statement=u64be(b,20);let authority=u32be(b,28);let epoch=u32be(b,32);let replay=u64be(b,36);let provenance=u64be(b,44);let outcome=b[52];if magic!=MAGIC||flags!=0||b[53]!=0||b[54]!=0||b[55]!=0{return false}let (em,ed)=if mode=="manual"{if v<3||v>av||v>5{return false}let mm=match mask(v){Some(x)=>x,None=>return false};let dd=match digest(v,mm){Some(x)=>x,None=>return false};(mm,dd)}else{let (pv,pm,pd)=match ph.and_then(policy){Some(x)=>x,None=>return false};if pv>5||(pm&!KNOWN_MASK)!=0||digest(pv,pm)!=Some(pd)||v!=pv{return false}(pm,pd)};if m!=em||d!=ed||(m&!KNOWN_MASK)!=0{return false}if statement!=STATEMENT||authority!=AUTHORITY||epoch!=EPOCH{return false}if m&8!=0&&replay==0{return false}if m&16!=0&&provenance==0{return false}if m&32!=0&&outcome!=1{return false}true}
fn main(){let a:Vec<String>=env::args().collect();let mut mode="".to_string();let mut av=0u16;let mut ph:Option<String>=None;let mut input="".to_string();let mut i=1;while i<a.len(){match a[i].as_str(){"--mode"=>{i+=1;mode=a[i].clone()},"--artifact-version"=>{i+=1;av=a[i].parse().unwrap()},"--policy-hex"=>{i+=1;ph=Some(a[i].clone())},x=>input=x.to_string()}i+=1;}let text=fs::read_to_string(input).unwrap();let mut out=Vec::new();for line in text.lines(){if line.is_empty(){continue}let p:Vec<&str>=line.split('\t').collect();let raw=hex(p[2]).unwrap();out.push(format!("{}\t{}",p[0],if validate(&raw,&mode,av,ph.as_deref()){1}else{0}));}println!("{}",out.join("\n"));}